package verify

import (
	"encoding/json"
	"os"
	"path/filepath"
	"testing"
)

// fixtures/konect-releases is a copy of the train's vectors (sparkhub-workday-gateway/fixtures/konect-releases,
// generated by scripts/gen-konect-release-fixtures.ts). The Go verifier must give the train's answer for every case.
type vectors struct {
	Schema string `json:"schema"` // konect-release-fixtures/1
	Keys   []struct {
		KeyID string `json:"keyId"`
		SPKI  string `json:"spki"`
	} `json:"keys"`
	Cases []struct {
		Name          string   `json:"name"`
		Dir           string   `json:"dir"`
		TrustedKeyIDs []string `json:"trustedKeyIds"`
		Expect        struct {
			Version     string  `json:"version"`
			Environment string  `json:"environment"`
			Platform    *string `json:"platform"`
		} `json:"expect"`
		Result struct {
			OK             bool     `json:"ok"`
			Code           string   `json:"code"`
			KeyIDs         []string `json:"keyIds"`
			Artifact       *string  `json:"artifact"`
			ManifestSHA256 string   `json:"manifestSha256"`
		} `json:"result"`
	} `json:"cases"`
}

func TestTrainFixtures(t *testing.T) {
	dir := filepath.Join("..", "..", "fixtures", "konect-releases")
	raw, err := os.ReadFile(filepath.Join(dir, "vectors.json"))
	if err != nil {
		t.Fatal(err)
	}
	var v vectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatal(err)
	}
	if v.Schema != "konect-release-fixtures/1" || len(v.Cases) < 40 {
		t.Fatalf("unexpected vectors: schema %q, %d cases", v.Schema, len(v.Cases))
	}
	spki := map[string]string{}
	for _, k := range v.Keys {
		spki[k.KeyID] = k.SPKI
	}
	for _, c := range v.Cases {
		t.Run(c.Name, func(t *testing.T) {
			m, err := os.ReadFile(filepath.Join(dir, "cases", c.Dir, "manifest.json"))
			if err != nil {
				t.Fatal(err)
			}
			s, err := os.ReadFile(filepath.Join(dir, "cases", c.Dir, "manifest.sig.json"))
			if err != nil {
				t.Fatal(err)
			}
			got := "ok"
			var res *Result
			keys, kerr := fixtureKeys(c.TrustedKeyIDs, spki)
			if kerr != nil {
				got = RuleKeysInvalid
			} else {
				platform := ""
				if c.Expect.Platform != nil {
					platform = *c.Expect.Platform
				}
				res, err = Release(m, s, keys, Expect{Version: c.Expect.Version, Environment: c.Expect.Environment, Platform: platform})
				if err != nil {
					got = RuleOf(err)
				}
			}
			want := "ok"
			if !c.Result.OK {
				want = c.Result.Code
			}
			if got != want {
				t.Fatalf("got %q, want %q", got, want)
			}
			if res == nil {
				return
			}
			if res.ManifestSHA256 != c.Result.ManifestSHA256 || len(res.KeyIDs) != len(c.Result.KeyIDs) {
				t.Fatalf("result %+v, want %+v", res, c.Result)
			}
			for i := range res.KeyIDs {
				if res.KeyIDs[i] != c.Result.KeyIDs[i] {
					t.Fatalf("keyIds %v, want %v", res.KeyIDs, c.Result.KeyIDs)
				}
			}
			wantArtifact := ""
			if c.Result.Artifact != nil {
				wantArtifact = *c.Result.Artifact
			}
			if res.Artifact.Name != wantArtifact {
				t.Fatalf("artifact %q, want %q", res.Artifact.Name, wantArtifact)
			}
		})
	}
}

// fixtureKeys parses the trusted keys of a case: a key that is not a P-256 SPKI (P-384, a point off the curve) is
// keys_invalid, as in the train (the bootstrap's compiled keys panic at start instead: a build defect).
func fixtureKeys(ids []string, spki map[string]string) ([]Key, error) {
	var keys []Key
	for _, id := range ids {
		k, err := ParseKeySPKI(id, spki[id])
		if err != nil {
			return nil, err
		}
		keys = append(keys, k)
	}
	return keys, nil
}

// A real release, signed in AWS KMS by konect-release-a (Konect v0.7.0-rc.1, the GitHub pre-release's
// manifest.json and manifest.sig.json): the COMPILED keys accept it, on preprod and dev, for every platform; prod
// refuses it (prerelease).
func TestRealKMSSignedRelease(t *testing.T) {
	dir := filepath.Join("..", "..", "fixtures", "konect-release-real", "v0.7.0-rc.1")
	m, err := os.ReadFile(filepath.Join(dir, "manifest.json"))
	if err != nil {
		t.Fatal(err)
	}
	s, err := os.ReadFile(filepath.Join(dir, "manifest.sig.json"))
	if err != nil {
		t.Fatal(err)
	}
	keys := TrustedKeys()
	for _, env := range []string{"preprod", "dev"} {
		for p := range artifacts {
			r, err := Release(m, s, keys, Expect{Version: "0.7.0-rc.1", Environment: env, Platform: p})
			if err != nil {
				t.Fatalf("%s %s: %v", env, p, err)
			}
			if r.KeyID != "konect-release-a" || r.Artifact.Name != ArtifactName(p) ||
				r.ManifestSHA256 != "eccddd030abd8e7b186a45ec8abce6227456361749bf882394f422a711e2343e" {
				t.Fatalf("%s %s: %+v", env, p, r)
			}
		}
	}
	if _, err := Release(m, s, keys, Expect{Version: "0.7.0-rc.1", Environment: "prod", Platform: "linux-x64"}); RuleOf(err) != RuleChannelRefused {
		t.Fatalf("prod: %v", err)
	}
	// One flipped byte in the manifest: no longer signed.
	bad := append([]byte(nil), m...)
	bad[len(bad)/2] ^= 1
	if _, err := Release(bad, s, keys, Expect{Version: "0.7.0-rc.1", Environment: "preprod", Platform: "linux-x64"}); RuleOf(err) != RuleSigNoneValid {
		t.Fatalf("flipped: %v", err)
	}
}
